        addBlobToContainer(containerName, view.getBlobStore().blobBuilder(key).userMetadata(ImmutableMap.of("adrian", "powderpuff")).payload(TEST_STRING).contentType(MediaType.TEXT_PLAIN).contentMD5(Hashing.md5().newHasher().putString(TEST_STRING, Charsets.UTF_8).hash()).build());
