@Test(groups = "live")
public void testCreateBucket() {
    BucketTemplate logTemplate = new BucketTemplate().name(LOG_BUCKET_NAME);
    Bucket logResponse = api().createBucket(PROJECT_NUMBER, logTemplate);
    assertNotNull(logResponse);
    BucketAccessControls acl = BucketAccessControls.builder().bucket(BUCKET_NAME).entity("allUsers").role(Role.OWNER).build();
    ObjectAccessControls oac = ObjectAccessControls.builder().bucket(BUCKET_NAME).entity("allUsers").role(ObjectRole.OWNER).build();
    Cors cors = Cors.create(Arrays.asList("http://example.appspot.com"), Arrays.asList("GET", "HEAD"), Arrays.asList("x-meta-goog-custom"), 10);
    Versioning version = Versioning.create(true);
    Logging log = Logging.create(LOG_BUCKET_NAME, BUCKET_NAME);
    BucketTemplate template = new BucketTemplate().name(BUCKET_NAME).addAcl(acl).addDefaultObjectAccessControls(oac).versioning(version).location(Location.US_CENTRAL2).logging(log).storageClass(StorageClass.DURABLE_REDUCED_AVAILABILITY).addCORS(cors);
    Bucket response = api().createBucket(PROJECT_NUMBER, template);
    assertNotNull(response);
    assertNotNull(response.cors());
    assertTrue(response.cors().size() == 1);
    assertEquals(response.name(), BUCKET_NAME);
    assertEquals(response.location(), Location.US_CENTRAL2);
    assertThat(response.storageClass()).isEqualTo(StorageClass.DURABLE_REDUCED_AVAILABILITY);
    assertTrue(response.versioning().enabled());
}

